import 'dart:async';import 'package:flutter/material.dart';import 'package:google_fonts/google_fonts.dart';import 'package:worldtravel/screen/onboarding_screen.dart';class SplashScreen extends StatefulWidget {  const SplashScreen({super.key});  @override  State<SplashScreen> createState() => _SplashScreenState();}class _SplashScreenState extends State<SplashScreen> {  @override  void initState() {    super.initState();    Timer(Duration(seconds: 3), () {      Navigator.pushReplacement(        context,        MaterialPageRoute(builder: (context) => const OnboardingScreen()),      );    });  }  Widget build(BuildContext context) {    return Scaffold(      backgroundColor: const Color(0xFFFF4B4B),      body: Stack(        children: [          Positioned(            top: 150,            left: 20,            child: Image.asset(              'asset/images/Frame1.png',              width: 190,              height: 190,            ),          ),          Center(            child: Text(              'World Travel',              style: GoogleFonts.novaScript(                fontSize: 40,                fontWeight: FontWeight.bold,                color: Colors.white,              ),              textAlign: TextAlign.center,            ),          ),          Positioned(            bottom: 100,            right: 20,            child: Image.asset(              'asset/images/Frame2.png',              width: 190,              height: 190,            ),          ),        ],      ),    );  }}